INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'hi') AND slug = 'polite-requests'), (SELECT id FROM languages WHERE code = 'en'), 'Polite requests: the -iye ending', '“Dena” is casual (fine at stalls); “dijiye” is polite (restaurants, shops). To sound more polite, use “-iye” verb endings and add “ji”: dena → dijiye, chaloge → chalenge, bhaiya → bhaiya ji.');
